(function(){
  function tag(el){
    if(el.getAttribute("inputmode")) return;
    el.setAttribute("inputmode", /^invwt-/.test(el.id) ? "decimal" : "numeric");
    if(!el.getAttribute("enterkeyhint")) el.setAttribute("enterkeyhint","done");
  }
  function sweep(root){
    if(root && root.querySelectorAll)
      root.querySelectorAll('input[type="number"]').forEach(tag);
  }
  document.addEventListener("DOMContentLoaded", function(){
    sweep(document);
    if(!("MutationObserver" in window) || !document.body) return;
    new MutationObserver(function(muts){
      muts.forEach(function(m){
        m.addedNodes.forEach(function(n){
          if(n.nodeType !== 1) return;
          if(n.matches && n.matches('input[type="number"]')) tag(n);
          sweep(n);
        });
      });
    }).observe(document.body, {childList:true, subtree:true});
