    if(key === "core" || key === "mini") return false;            // landing tab + print-standee helper never dot
    if(key === "companion") return (companions||[]).length > 0;
    if(key === "spells") return spellSheetUsed(0);                // main sheet: class set, any spell named, or anything prepared
