// P1 durability: nudge a backup-to-file when local data may be stale. localStorage can be wiped by the
// browser (iOS Safari clears it after ~7 days of no use), and the exported HTML file is the only durable
// store. We track the last time THIS character was downloaded; if it's been too long (or never), and the
// sheet actually holds something, we surface a dismissible banner on load.
const BACKUP_KEY = KEY + "_exported";
const BACKUP_THRESHOLD_MS = 3 * 24*60*60*1000;   // 3 days — well inside the iOS 7-day eviction window
function characterHasContent(){
  const filled = sel => { const e = document.querySelector(sel); return !!(e && (e.value||"").trim()); };
  if(filled("#charname") || filled("#classlevel")) return true;
  if((companions||[]).length) return true;
  return !!document.querySelector(".ptab.has-content");
}
function stampBackup(){ try{ localStorage.setItem(BACKUP_KEY, String(Date.now())); }catch(e){} }
function hideBackupBanner(){ const b = $("backup-banner"); if(b) b.hidden = true; }
function maybeShowBackupBanner(){
  const b = $("backup-banner"); if(!b) return;
  if(sessionStorage.getItem(BACKUP_KEY + "_dismissed")){ b.hidden = true; return; }   // dismissed this session
  if(!characterHasContent()){ b.hidden = true; return; }                              // nothing worth backing up
  let ts = 0; try{ ts = +localStorage.getItem(BACKUP_KEY) || 0; }catch(e){}
  b.hidden = !(Date.now() - ts > BACKUP_THRESHOLD_MS);                                // stale or never exported → show
}
